-- =============================================================================
-- TASKO — DỮ LIỆU MẪU TOÀN DIỆN (POSTGRESQL 15+ / TYPEORM SCHEMA)
-- =============================================================================
-- Mô tả:
--   * 5 Roles + 9 Permissions RBAC (khớp 100% RbacSeederService)
--   * 12 Users (mật khẩu chung: Tasko@123456 — bcrypt cost 10 thật)
--   * 3 Workspaces + 23 Workspace Members
--   * 6 Projects (2 SCRUM, 2 SCRUMBAN, 2 KANBAN) + 41 Project Members
--   * 26 Statuses (kèm WIP Limits), 12 Workflows, 24 WorkTypes, 24 CustomFields
--   * 14 Sprints (COMPLETED / ACTIVE / PLANNED quanh CURRENT_DATE)
--   * 190 Tasks & Subtasks (33 Task cha + 101 Subtasks + 56 Task độc lập)
--   * ~500+ Custom Field Values (SELECT, TEXT, NUMBER, DATE)
--   * Toàn bộ ngày tháng dùng CURRENT_DATE + INTERVAL nên luôn đẹp ở tháng hiện tại
--   * Idempotent: chạy lại nhiều lần không lỗi trùng khóa (ON CONFLICT DO NOTHING)
-- =============================================================================

-- Bỏ comment dòng dưới đây nếu muốn XÓA SẠCH dữ liệu cũ trước khi nạp lại từ đầu:
-- TRUNCATE TABLE custom_field_values, tasks, sprints, custom_fields, workflow_transitions, workflows, work_types, statuses, project_members, projects, workspace_members, workspaces, sessions, email_verifications, password_reset_tokens, users RESTART IDENTITY CASCADE;

BEGIN;

-- =============================================================================
-- 1. RBAC: PERMISSIONS, ROLES & ROLE_PERMISSIONS
-- =============================================================================
ON CONFLICT (code) DO NOTHING;

ON CONFLICT (name, scope) DO NOTHING;

SELECT r.id, p.id FROM (VALUES
  ('ADMIN', 'WORKSPACE', 'WORKSPACE_ADMIN'),
  ('ADMIN', 'WORKSPACE', 'WORKSPACE_MEMBER_MANAGE'),
  ('ADMIN', 'WORKSPACE', 'WORKSPACE_PROJECT_VIEW'),
  ('ADMIN', 'WORKSPACE', 'PROJECT_CONFIGURE'),
  ('ADMIN', 'WORKSPACE', 'PROJECT_MANAGE'),
  ('ADMIN', 'WORKSPACE', 'SPRINT_MANAGE'),
  ('ADMIN', 'WORKSPACE', 'TASK_WRITE'),
  ('ADMIN', 'WORKSPACE', 'COLLAB_AND_AI_USE'),
  ('ADMIN', 'WORKSPACE', 'PROJECT_VIEW_ONLY'),
  ('MEMBER', 'WORKSPACE', 'WORKSPACE_PROJECT_VIEW'),
  ('OWNER', 'PROJECT', 'PROJECT_CONFIGURE'),
  ('OWNER', 'PROJECT', 'PROJECT_MANAGE'),
  ('OWNER', 'PROJECT', 'SPRINT_MANAGE'),
  ('OWNER', 'PROJECT', 'TASK_WRITE'),
  ('OWNER', 'PROJECT', 'COLLAB_AND_AI_USE'),
  ('OWNER', 'PROJECT', 'PROJECT_VIEW_ONLY'),
  ('MEMBER', 'PROJECT', 'TASK_WRITE'),
  ('MEMBER', 'PROJECT', 'COLLAB_AND_AI_USE'),
  ('MEMBER', 'PROJECT', 'PROJECT_VIEW_ONLY'),
  ('VIEWER', 'PROJECT', 'PROJECT_VIEW_ONLY')
) AS v(role_name, role_scope, perm_code)
JOIN roles r ON r.name = v.role_name AND r.scope::text = v.role_scope
JOIN permissions p ON p.code = v.perm_code
ON CONFLICT (role_id, permission_id) DO NOTHING;

-- =============================================================================
-- 2. USERS (12 tài khoản demo — Mật khẩu: Tasko@123456)
-- =============================================================================
ON CONFLICT (email) DO NOTHING;

-- =============================================================================
-- 3. WORKSPACES (3 không gian làm việc) & WORKSPACE_MEMBERS
-- =============================================================================
ON CONFLICT (slug) DO NOTHING;

ON CONFLICT (workspace_id, user_id) DO NOTHING;

-- =============================================================================
-- 4. PROJECTS (6 dự án: 2 SCRUM, 2 SCRUMBAN, 2 KANBAN) & PROJECT_MEMBERS
-- =============================================================================
ON CONFLICT (workspace_id, key) DO NOTHING;

ON CONFLICT (project_id, user_id) DO NOTHING;

-- =============================================================================
-- 5. STATUSES, WORKFLOWS, WORKFLOW_TRANSITIONS, WORK_TYPES & CUSTOM_FIELDS
-- =============================================================================
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (workflow_id, from_status_id, to_status_id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- =============================================================================
-- 6. SPRINTS (14 Sprints cho 4 dự án SCRUM & SCRUMBAN)
-- =============================================================================
ON CONFLICT (id) DO NOTHING;

-- =============================================================================
-- 7A. TASKS CHA & TASKS ĐỘC LẬP (Chèn trước để thỏa mãn FK parent_task_id)
-- =============================================================================
ON CONFLICT (project_id, task_key) DO NOTHING;

-- =============================================================================
-- 7B. SUBTASKS (Chèn sau Task cha — parent_task_id trỏ tới Task cha ở 7A)
-- =============================================================================
ON CONFLICT (project_id, task_key) DO NOTHING;

-- =============================================================================
-- 8. CUSTOM FIELD VALUES (Giá trị trường tùy chỉnh cho các Task)
-- =============================================================================
ON CONFLICT (task_id, custom_field_id) DO NOTHING;

COMMIT;

-- =============================================================================
-- HƯỚNG DẪN CHẠY & DANH SÁCH TÀI KHOẢN DEMO (Mật khẩu chung: Tasko@123456)
-- =============================================================================
-- Câu lệnh nạp dữ liệu bằng psql:
--   psql -h localhost -p 5432 -U postgres -d tasko -v ON_ERROR_STOP=1 -f backend/src/database/seed.sql
--
-- Kiểm tra số lượng bản ghi sau khi nạp:
--   SELECT 'users' AS tbl, COUNT(*) FROM users
--   UNION ALL SELECT 'workspaces', COUNT(*) FROM workspaces
--   UNION ALL SELECT 'workspace_members', COUNT(*) FROM workspace_members
--   UNION ALL SELECT 'projects', COUNT(*) FROM projects
--   UNION ALL SELECT 'project_members', COUNT(*) FROM project_members
--   UNION ALL SELECT 'statuses', COUNT(*) FROM statuses
--   UNION ALL SELECT 'workflows', COUNT(*) FROM workflows
--   UNION ALL SELECT 'workflow_transitions', COUNT(*) FROM workflow_transitions
--   UNION ALL SELECT 'work_types', COUNT(*) FROM work_types
--   UNION ALL SELECT 'custom_fields', COUNT(*) FROM custom_fields
--   UNION ALL SELECT 'sprints', COUNT(*) FROM sprints
--   UNION ALL SELECT 'tasks', COUNT(*) FROM tasks
--   UNION ALL SELECT 'custom_field_values', COUNT(*) FROM custom_field_values;
