INSERT INTO workspaces (id, name, slug, description, owner_id) VALUES
  ('20000000-0000-4000-8000-000000000001', 'TechNova Solutions', 'technova-solutions', 'Không gian làm việc chính của khối Kỹ thuật & Sản phẩm TechNova Solutions, quản lý các dự án thương mại điện tử, fintech, ERP và hạ tầng Cloud.', '10000000-0000-4000-8000-000000000001'),
  ('20000000-0000-4000-8000-000000000002', 'Creative Studio VN', 'creative-studio-vn', 'Không gian sáng tạo của phòng Marketing & Thiết kế thương hiệu, điều phối chiến dịch ra mắt sản phẩm, nội dung số và nhận diện thương hiệu.', '10000000-0000-4000-8000-000000000002'),
  ('20000000-0000-4000-8000-000000000003', 'Tasko Operations', 'tasko-operations', 'Không gian vận hành hệ thống, xử lý sự cố khách hàng (SLA), giám sát dịch vụ và tối ưu quy trình hỗ trợ kỹ thuật 24/7.', '10000000-0000-4000-8000-000000000001')
