INSERT INTO projects (id, name, key, color, description, methodology, start_date, end_date, settings, workspace_id, owner_id) VALUES
  ('30000000-0000-4000-8000-000000000001', 'Nền tảng Thương mại Điện tử ShopX', 'SHOPX', 'bg-indigo-600', 'Xây dựng sàn thương mại điện tử đa nhà bán hàng (multi-vendor) với giỏ hàng real-time, thanh toán VNPay/MoMo, flash sale chịu tải cao và ứng dụng mua sắm di động.', 'SCRUM', (CURRENT_DATE - INTERVAL '40 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '60 days' + TIME '09:00:00')::timestamptz, '{"defaultView":"board","enableWipLimits":true,"enableStoryPoints":true}'::jsonb, '20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000002'),
  ('30000000-0000-4000-8000-000000000002', 'Ứng dụng Ví điện tử & Thanh toán FinPay', 'FINPAY', 'bg-emerald-600', 'Phát triển ứng dụng ví điện tử tuân thủ chuẩn bảo mật PCI-DSS, hỗ trợ định danh eKYC, chuyển tiền VietQR 24/7, thanh toán hóa đơn và sổ cái giao dịch real-time.', 'SCRUM', (CURRENT_DATE - INTERVAL '35 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '55 days' + TIME '09:00:00')::timestamptz, '{"defaultView":"board","enableWipLimits":true,"enableStoryPoints":true}'::jsonb, '20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000003'),
  ('30000000-0000-4000-8000-000000000003', 'Hệ thống Quản trị Nội bộ Enterprise ERP', 'ERP', 'bg-violet-600', 'Số hóa toàn bộ quy trình quản trị nhân sự (HRM), chấm công tính lương, quản lý tồn kho đa chi nhánh và luồng phê duyệt đề xuất tài chính nội bộ.', 'SCRUMBAN', (CURRENT_DATE - INTERVAL '30 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '50 days' + TIME '09:00:00')::timestamptz, '{"defaultView":"board","enableWipLimits":true,"enableStoryPoints":true}'::jsonb, '20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000002'),
  ('30000000-0000-4000-8000-000000000004', 'Nâng cấp Hạ tầng Cloud & CI/CD', 'CLOUD', 'bg-sky-600', 'Chuyển đổi toàn bộ dịch vụ sang cụm Kubernetes (EKS) có tự động mở rộng tải, chuẩn hóa Infrastructure as Code bằng Terraform và hệ thống giám sát OpenTelemetry.', 'SCRUMBAN', (CURRENT_DATE - INTERVAL '25 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '45 days' + TIME '09:00:00')::timestamptz, '{"defaultView":"board","enableWipLimits":true,"enableStoryPoints":true}'::jsonb, '20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000003'),
  ('30000000-0000-4000-8000-000000000005', 'Chiến dịch Ra mắt Sản phẩm & Truyền thông', 'MKTQ4', 'bg-rose-600', 'Điều phối toàn bộ kế hoạch ra mắt nền tảng Tasko & ShopX: sản xuất bộ nhận diện, landing page chuyển đổi cao, chiến dịch quảng cáo đa kênh và sự kiện ra mắt báo chí.', 'KANBAN', (CURRENT_DATE - INTERVAL '22 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '38 days' + TIME '09:00:00')::timestamptz, '{"defaultView":"board","enableWipLimits":true,"enableStoryPoints":true}'::jsonb, '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000002'),
  ('30000000-0000-4000-8000-000000000006', 'Trung tâm Hỗ trợ Kỹ thuật & Vận hành', 'OPS', 'bg-amber-600', 'Tiếp nhận và xử lý sự cố kỹ thuật khách hàng theo cam kết SLA, vận hành bảo trì định kỳ, quản lý bản vá bảo mật và nâng cao độ ổn định dịch vụ.', 'KANBAN', (CURRENT_DATE - INTERVAL '20 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '35 days' + TIME '09:00:00')::timestamptz, '{"defaultView":"board","enableWipLimits":true,"enableStoryPoints":true}'::jsonb, '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000001')
