INSERT INTO sprints (id, project_id, name, goal, status, start_date, end_date, position) VALUES
  ('40000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 'Sprint 1: Nền tảng Danh mục & Tìm kiếm', 'Hoàn thiện kiến trúc catalog sản phẩm, bộ lọc đa chiều và tìm kiếm Elasticsearch tốc độ dưới 120ms.', 'COMPLETED', (CURRENT_DATE - INTERVAL '38 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE - INTERVAL '25 days' + TIME '09:00:00')::timestamptz, 1000),
  ('40000000-0000-4000-8000-000000000002', '30000000-0000-4000-8000-000000000001', 'Sprint 2: Giỏ hàng & Thanh toán đa kênh', 'Tích hợp giỏ hàng đồng bộ đa thiết bị, mã giảm giá và cổng thanh toán VNPay/MoMo.', 'COMPLETED', (CURRENT_DATE - INTERVAL '24 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE - INTERVAL '11 days' + TIME '09:00:00')::timestamptz, 2000),
  ('40000000-0000-4000-8000-000000000003', '30000000-0000-4000-8000-000000000001', 'Sprint 3: Flash Sale & Trải nghiệm Nhà bán hàng', 'Triển khai cơ chế giữ tồn kho Redis cho Flash Sale 10.000 đơn/phút và trang quản trị Seller Center.', 'ACTIVE', (CURRENT_DATE - INTERVAL '6 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '8 days' + TIME '09:00:00')::timestamptz, 3000),
  ('40000000-0000-4000-8000-000000000004', '30000000-0000-4000-8000-000000000001', 'Sprint 4: Gợi ý AI & Chăm sóc khách hàng', 'Tích hợp hệ thống gợi ý sản phẩm cá nhân hóa và chat trực tiếp giữa người mua và nhà bán.', 'PLANNED', (CURRENT_DATE + INTERVAL '9 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '23 days' + TIME '09:00:00')::timestamptz, 4000),
  ('40000000-0000-4000-8000-000000000005', '30000000-0000-4000-8000-000000000002', 'Sprint 1: Định danh eKYC & Bảo mật sinh trắc học', 'Hoàn thiện luồng quét CCCD gắn chip NFC, đối chiếu khuôn mặt Liveness và đăng nhập FaceID/TouchID.', 'COMPLETED', (CURRENT_DATE - INTERVAL '35 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE - INTERVAL '22 days' + TIME '09:00:00')::timestamptz, 1000),
  ('40000000-0000-4000-8000-000000000006', '30000000-0000-4000-8000-000000000002', 'Sprint 2: Sổ cái lõi & Liên kết ngân hàng Napas', 'Xây dựng Core Ledger bút toán kép và nạp/rút tiền qua 15 ngân hàng nội địa.', 'COMPLETED', (CURRENT_DATE - INTERVAL '21 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE - INTERVAL '8 days' + TIME '09:00:00')::timestamptz, 2000),
  ('40000000-0000-4000-8000-000000000007', '30000000-0000-4000-8000-000000000002', 'Sprint 3: Thanh toán VietQR & Chia hóa đơn nhóm', 'Triển khai quét mã VietQR động/tĩnh tốc độ cao và tính năng chia tiền nhóm cho giới trẻ.', 'ACTIVE', (CURRENT_DATE - INTERVAL '5 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '9 days' + TIME '09:00:00')::timestamptz, 3000),
  ('40000000-0000-4000-8000-000000000008', '30000000-0000-4000-8000-000000000002', 'Sprint 4: Chống gian lận (Anti-Fraud) & Đối soát tự động', 'Áp dụng luật cảnh báo giao dịch bất thường theo thời gian thực và đối soát cuối ngày với Napas.', 'PLANNED', (CURRENT_DATE + INTERVAL '10 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '24 days' + TIME '09:00:00')::timestamptz, 4000),
  ('40000000-0000-4000-8000-000000000009', '30000000-0000-4000-8000-000000000003', 'Đợt 1: Phân hệ Hồ sơ Nhân sự & Chấm công', 'Hoàn thiện cây sơ đồ tổ chức, đồng bộ máy chấm công khuôn mặt và quản lý đơn nghỉ phép.', 'COMPLETED', (CURRENT_DATE - INTERVAL '28 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE - INTERVAL '15 days' + TIME '09:00:00')::timestamptz, 1000),
  ('40000000-0000-4000-8000-000000000010', '30000000-0000-4000-8000-000000000003', 'Đợt 2: Tính lương tự động & Duyệt chi tài chính', 'Triển khai công thức tính lương, thuế TNCN, BHXH và quy trình phê duyệt đề xuất thanh toán đa cấp.', 'ACTIVE', (CURRENT_DATE - INTERVAL '6 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '8 days' + TIME '09:00:00')::timestamptz, 2000),
  ('40000000-0000-4000-8000-000000000011', '30000000-0000-4000-8000-000000000003', 'Đợt 3: Quản lý Tài sản & Kho vật tư đa chi nhánh', 'Theo dõi cấp phát thiết bị laptop theo mã QR và kiểm kê kho định kỳ giữa văn phòng HCM & Hà Nội.', 'PLANNED', (CURRENT_DATE + INTERVAL '9 days' + TIME '09:00:00')::timestamptz, (CURRENT_DATE + INTERVAL '23 days' + TIME '09:00:00')::timestamptz, 3000),
